function @@proc@@(p_qty in number) return varchar2 is
begin
  if p_qty > @@num@@ then -- @expect
    return 'bulk';
  end if;
  if p_qty = @@num@@ then -- @expect
    return 'limit';
  end if;
  if p_qty + 5 < @@num@@ then -- @expect
    return 'small';
  end if;
  return 'normal';
end @@proc@@;

function @@proc@@(p_a in number) return varchar2 is
  l_total number;
  l_label varchar2(10);
begin
  l_total := p_a * @@num@@; -- @expect
  l_label := case
               when p_a > @@num@@ then 'big' -- @expect
               else 'small'
             end;
  if l_total > @@num@@ then -- @expect
    l_label := 'huge';
  end if;
  return l_label;
end @@proc@@;

procedure @@proc@@(p_a in varchar2, p_b in varchar2, p_c in varchar2) is
  l_a varchar2(50);
  l_b varchar2(50);
  l_c varchar2(50);
begin
  l_a := nvl(p_a, '@@str@@'); -- @expect
  l_b := coalesce(p_b, '@@str@@'); -- @expect
  l_c := replace(p_c, ' ', '@@str@@'); -- @expect
  dbms_output.put_line(l_a || l_b || l_c);
end @@proc@@;

