function @@proc@@(p_a in number, p_b in number) return number is
  l_r number := 0;
begin
  if p_a > 0 then
    l_r := l_r + 1;
  end if;
  if p_b > 0 then
    l_r := l_r + 1;
  end if;
  if p_a + p_b > 1 then
    l_r := l_r + 1;
  end if;
  return l_r;
end @@proc@@;

procedure @@proc@@(p_a in number) is
begin
  if p_a > @@num@@ then
    dbms_output.put_line('@@str@@');
  end if;
  if p_a < @@num@@ then
    dbms_output.put_line('@@str@@');
  end if;
end @@proc@@;

function @@proc@@(p_a in number, p_b in number, p_c in number) return number is
  c_limit constant number := @@num@@;
  l_n number := 0;
begin
  if p_a > c_limit then
    l_n := l_n + 1;
  end if;
  if p_b > c_limit then
    l_n := l_n + 1;
  end if;
  if p_c > c_limit then
    l_n := l_n + 1;
  end if;
  return l_n;
end @@proc@@;

function @@proc@@(p_a in varchar2, p_b in varchar2, p_c in varchar2) return varchar2 is
  l_out varchar2(400);
begin
  l_out := p_a || ',' || p_b;
  l_out := l_out || ',' || p_c;
  l_out := l_out || ';' || p_a;
  l_out := l_out || ';' || p_b;
  l_out := l_out || '|' || p_c;
  l_out := l_out || '|' || p_a;
  return l_out;
end @@proc@@;

procedure @@proc@@(p_a in varchar2, p_b in varchar2, p_c in varchar2) is
  l_a varchar2(50);
  l_b varchar2(50);
  l_c varchar2(50);
begin
  l_a := nvl(p_a, '');
  l_b := nvl(p_b, '');
  l_c := nvl(p_c, '');
  dbms_output.put_line(l_a || l_b || l_c);
end @@proc@@;
